import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { repositoryStaleFenceProbeSchema, repositoryStaleFenceRequestHash } from "./repository-stale-fence-proof-context.js";

// Generated by the real TypeScript serializer; Go reads these same synthetic vectors.
const fixture = JSON.parse(readFileSync(new URL(
  "../../../services/domain-api/internal/target/testdata/repository-stale-fence-hash-v1.json", import.meta.url,
), "utf8")) as { schemaVersion: number; synthetic: boolean; vectors: {
  name: string; probe: unknown; serializedInput: string; requestSha256: string;
}[] };

describe("fixed stale-heartbeat TS/Go hash contract", () => {
  it.each(fixture.vectors)("preserves Go struct order and whole-second UTC for $name", vector => {
    expect(fixture.schemaVersion).toBe(1);
    expect(fixture.synthetic).toBe(true);
    const probe = repositoryStaleFenceProbeSchema.parse(vector.probe);
    expect(JSON.stringify(probe.input)).toBe(vector.serializedInput);
    expect(repositoryStaleFenceRequestHash(probe)).toBe(vector.requestSha256);
    expect(probe.input).not.toHaveProperty("payload");
  });

  it.each([
    "2026-02-30T00:00:00Z", "2025-02-29T00:00:00Z", "2026-04-31T00:00:00Z",
    "2026-13-01T00:00:00Z", "2026-10-16T24:00:00Z", "2026-10-16T00:00:60Z",
    "2026-10-16T00:00:00.000Z", "2026-10-16T00:00:00+00:00",
  ])("rejects timestamps outside the Go-compatible fixed wire: %s", emittedAt => {
    const probe = repositoryStaleFenceProbeSchema.parse(fixture.vectors[0]!.probe);
    expect(repositoryStaleFenceProbeSchema.safeParse({ ...probe, input: { ...probe.input, emittedAt } }).success).toBe(false);
  });

  it.each([{}, null, { marker: "not-a-payload-free-probe" }])("rejects an explicitly supplied payload %j", payload => {
    const probe = repositoryStaleFenceProbeSchema.parse(fixture.vectors[0]!.probe);
    expect(repositoryStaleFenceProbeSchema.safeParse({ ...probe, input: { ...probe.input, payload } }).success).toBe(false);
  });

  it.each([{ artifacts: [] }, { extendLeaseSeconds: 0 }, { fencingToken: Number.MAX_SAFE_INTEGER + 1 }, { cursor: Number.MAX_SAFE_INTEGER + 1 }])(
    "rejects extensions outside the fixed request shape %j", extension => {
      const probe = repositoryStaleFenceProbeSchema.parse(fixture.vectors[0]!.probe);
      expect(repositoryStaleFenceProbeSchema.safeParse({ ...probe, input: { ...probe.input, ...extension } }).success).toBe(false);
    },
  );
});
